package app.shubian;

import android.app.*;import android.content.ContentValues;import android.os.Environment;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.provider.Settings;import android.speech.tts.TextToSpeech;import android.view.*;import android.view.inputmethod.EditorInfo;import android.widget.*;import android.text.*;import java.util.*;import java.util.zip.*;import java.io.*;import java.security.*;import app.shubian.dict.DictDatabase;

public class MainActivity extends Activity {
  DictDatabase dict; TextToSpeech tts; FrameLayout root; EditText query; LinearLayout content; TextView title; ArrayList<String> recent=new ArrayList<>();
  int orange=Color.rgb(247,107,21), text=Color.rgb(28,32,36), muted=Color.rgb(96,100,108), faint=Color.rgb(139,141,152), fill=Color.rgb(240,240,243), bg=Color.rgb(252,252,253);
  @Override public void onCreate(Bundle b){super.onCreate(b); getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_VISIBLE|WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE); try{dict=DictDatabase.open(this);}catch(Exception e){} tts=new TextToSpeech(this,s->{if(tts!=null)tts.setLanguage(Locale.US);}); handleIntent(getIntent()); showLookup(null);}
  @Override protected void onNewIntent(Intent i){super.onNewIntent(i);handleIntent(i);}
  void handleIntent(Intent i){String q=i.getStringExtra(Intent.EXTRA_PROCESS_TEXT);if(q==null)q=i.getStringExtra("EXTRA_QUERY");if(q!=null){final String qq=q;new Handler().postDelayed(()->showCard(qq.trim(),null),180);}}
  TextView tv(String s,float sp,int color){TextView v=new TextView(this);v.setText(s);v.setTextSize(sp);v.setTextColor(color);v.setGravity(Gravity.CENTER_VERTICAL);v.setPadding(dp(16),dp(8),dp(16),dp(8));return v;}
  int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
  GradientDrawable bg(int color,float radius){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(dp((int)radius));return g;}
  void base(String screen){root=new FrameLayout(this);root.setBackgroundColor(bg);setContentView(root); LinearLayout shell=new LinearLayout(this);shell.setOrientation(LinearLayout.VERTICAL);root.addView(shell,new FrameLayout.LayoutParams(-1,-1));
    LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(dp(20),dp(10),dp(16),dp(6)); title=tv(screen,28,text);title.setTypeface(Typeface.DEFAULT,Typeface.BOLD);bar.addView(title,new LinearLayout.LayoutParams(0,dp(58),1)); TextView set=tv("⚙",26,orange);set.setGravity(Gravity.CENTER);set.setOnClickListener(v->showSettings());bar.addView(set,new LinearLayout.LayoutParams(dp(46),dp(46)));shell.addView(bar);
    content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);shell.addView(content,new LinearLayout.LayoutParams(-1,0,1));
    LinearLayout nav=new LinearLayout(this);nav.setGravity(Gravity.CENTER);nav.setPadding(0,dp(4),0,dp(4));nav.setBackgroundColor(Color.rgb(249,249,251));String[] ns={"⌕\n查单词","▦\n书库","☆\n生词本"};for(String n:ns){TextView b=tv(n,12,muted);b.setGravity(Gravity.CENTER);final String x=n; b.setOnClickListener(v->{if(x.contains("书库"))showLibrary();else if(x.contains("生词本"))showWords();else showLookup(null);});nav.addView(b,new LinearLayout.LayoutParams(0,dp(62),1));}shell.addView(nav);
  }
  void showLookup(String initial){base("查单词"); LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(20),0,dp(20),0);content.addView(box,new LinearLayout.LayoutParams(-1,-1));
    query=new EditText(this);query.setSingleLine(true);query.setHint("输入英文单词");query.setTextSize(28);query.setTypeface(Typeface.SERIF);query.setPadding(dp(18),0,dp(12),0);query.setBackground(bg(Color.rgb(249,249,251),18));box.addView(query,new LinearLayout.LayoutParams(-1,dp(60)));
    LinearLayout acts=new LinearLayout(this);acts.setGravity(Gravity.CENTER);acts.setPadding(0,dp(16),0,0);TextView cam=button("▣  拍一页");TextView pick=button("▤  从相册选");acts.addView(cam,new LinearLayout.LayoutParams(0,dp(48),1));LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(0,dp(48),1);pp.leftMargin=dp(12);acts.addView(pick,pp);box.addView(acts);cam.setOnClickListener(v->startCamera());pick.setOnClickListener(v->pickImage());
    TextView rt=tv("最近查过",14,faint);rt.setGravity(Gravity.CENTER);rt.setPadding(0,dp(32),0,dp(8));box.addView(rt);LinearLayout chips=new LinearLayout(this);chips.setGravity(Gravity.CENTER);box.addView(chips);for(String w:recent){TextView c=button(w);c.setTypeface(Typeface.SERIF);c.setTextSize(17);c.setOnClickListener(v->showCard(w,null));chips.addView(c,new LinearLayout.LayoutParams(-2,dp(42)));}
    query.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int d){}public void onTextChanged(CharSequence s,int a,int b,int c){renderResults(s.toString(),box,acts,rt,chips);}public void afterTextChanged(Editable e){}});query.setOnEditorActionListener((v,id,e)->{if(id==EditorInfo.IME_ACTION_SEARCH||id==EditorInfo.IME_ACTION_DONE){if(dict!=null){DictDatabase.Entry x=dict.lookup(query.getText().toString());if(x!=null)showCard(x.word,null);}return true;}return false;});if(initial!=null){query.setText(initial);query.setSelection(initial.length());}query.requestFocus();((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showSoftInput(query,android.view.inputmethod.InputMethodManager.SHOW_IMPLICIT);}
  TextView button(String s){TextView b=tv(s,17,text);b.setGravity(Gravity.CENTER);b.setBackground(bg(fill,14));return b;}
  void renderResults(String s,LinearLayout box,View acts,View rt,View chips){boolean has=!s.trim().isEmpty();acts.setVisibility(has?View.GONE:View.VISIBLE);rt.setVisibility(has?View.GONE:View.VISIBLE);chips.setVisibility(has?View.GONE:View.VISIBLE);if(box.getChildCount()>4)box.removeViews(4,box.getChildCount()-4);if(!has)return;LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);list.setPadding(0,dp(12),0,0);if(dict!=null)for(DictDatabase.Entry e:dict.prefix(s,12)){TextView row=tv(e.word+"\n"+(e.senses().isEmpty()?e.trans:e.senses().get(0)),17,text);row.setTypeface(Typeface.DEFAULT,Typeface.NORMAL);row.setPadding(dp(16),dp(10),dp(16),dp(10));row.setOnClickListener(v->showCard(e.word,null));list.addView(row,new LinearLayout.LayoutParams(-1,dp(64)));}box.addView(list,new LinearLayout.LayoutParams(-1,0,1));}
  void showCard(String word,String sentence){if(word==null||word.isEmpty())return;DictDatabase.Entry e=dict==null?null:dict.lookup(word);Dialog d=new Dialog(this);LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(dp(22),dp(12),dp(22),dp(22));l.setBackground(bg(bg,18));TextView h=tv(e==null?"词典里没有 "+word:e.word,28,text);h.setTypeface(Typeface.SERIF,Typeface.BOLD);l.addView(h);if(e!=null){TextView ph=tv(e.phonetic+"  🔊",14,muted);ph.setOnClickListener(v->{if(tts!=null)tts.speak(e.word,TextToSpeech.QUEUE_FLUSH,null,"word");});l.addView(ph);if(sentence!=null&&!sentence.isEmpty()){TextView ctx=tv("本句中\n正在判断…",17,text);ctx.setPadding(dp(12),dp(8),dp(12),dp(8));ctx.setBackground(bg(Color.rgb(255,239,214),12));l.addView(ctx);}LinearLayout senses=new LinearLayout(this);senses.setOrientation(LinearLayout.VERTICAL);for(String s:e.senses())senses.addView(tv("• "+s,17,text));l.addView(senses);TextView add=button("☆  加入生词本");add.setTextColor(Color.WHITE);add.setBackground(bg(orange,22));add.setOnClickListener(v->{saveWord(e);add.setText("已在生词本");});l.addView(add,new LinearLayout.LayoutParams(-1,dp(46)));if(!recent.contains(e.word)){recent.add(0,e.word);if(recent.size()>50)recent.remove(50);}}d.setContentView(l);Window w=d.getWindow();if(w!=null){w.setBackgroundDrawableResource(android.R.color.transparent);w.setLayout(-1,-2);}d.show();if(d.getWindow()!=null)d.getWindow().setLayout(-1,-2);}
  void saveWord(DictDatabase.Entry e){getSharedPreferences("words",0).edit().putString(e.word,e.trans).apply();}
  void showWords(){base("生词本");TextView export=tv("导出",17,orange);export.setOnClickListener(v->exportWords());content.addView(export,new LinearLayout.LayoutParams(-1,dp(44)));LinearLayout chips=new LinearLayout(this);for(String s:new String[]{"全部","书库","查单词"}){TextView c=button(s);chips.addView(c,new LinearLayout.LayoutParams(-2,dp(42)));}content.addView(chips);Map<String,?> all=getSharedPreferences("words",0).getAll();if(all.isEmpty()){TextView e=tv("还没有收藏的词",17,faint);e.setGravity(Gravity.CENTER);content.addView(e,new LinearLayout.LayoutParams(-1,0,1));}else{for(String k:all.keySet()){TextView row=tv(k+"\n查单词\n"+all.get(k),17,text);row.setPadding(dp(20),dp(12),dp(20),dp(12));content.addView(row,new LinearLayout.LayoutParams(-1,dp(82)));}}}
  
  void exportWords(){Map<String,?> all=getSharedPreferences("words",0).getAll();String name="书边译-生词本-"+new java.text.SimpleDateFormat("yyyyMMdd",Locale.US).format(new Date())+".csv";try{ContentValues cv=new ContentValues();cv.put(android.provider.MediaStore.Downloads.DISPLAY_NAME,name);cv.put(android.provider.MediaStore.Downloads.MIME_TYPE,"text/csv");cv.put(android.provider.MediaStore.Downloads.RELATIVE_PATH,Environment.DIRECTORY_DOWNLOADS);Uri u=getContentResolver().insert(android.provider.MediaStore.Downloads.EXTERNAL_CONTENT_URI,cv);if(u!=null){OutputStream o=getContentResolver().openOutputStream(u);o.write("word,lemma,phonetic,meaning,context_sense,sentence,source,added_at\n".getBytes());for(String k:all.keySet()){String line=k+","+k+",,"+String.valueOf(all.get(k)).replace("\n"," ")+",,,查单词,"+System.currentTimeMillis()+"\n";o.write(line.getBytes());}o.close();Toast.makeText(this,"已导出到下载",Toast.LENGTH_SHORT).show();}}catch(Exception e){Toast.makeText(this,"导出失败",Toast.LENGTH_SHORT).show();}}
  void showSettings(){base("设置");settingsRow("Jev API Key",true);TextView test=button("测试连接");test.setOnClickListener(v->Toast.makeText(this,"未配置或离线，稍后重试",Toast.LENGTH_SHORT).show());content.addView(test,new LinearLayout.LayoutParams(-1,dp(46)));settingsRow("读者水平",false);settingsRow("整句翻译接口地址",false);settingsRow("整句翻译模型",false);settingsRow("整句翻译 Key",true);Switch s=new Switch(this);s.setText("音量键翻页");s.setTextSize(17);s.setPadding(dp(20),dp(12),dp(20),dp(12));content.addView(s);TextView clear=tv("清除“认识”记录",17,text);clear.setPadding(dp(20),dp(18),dp(20),dp(18));content.addView(clear);TextView about=tv("关于\n版本 1.0\n词典来源 ECDICT（MIT）\n字体 Literata、Source Serif 4（OFL）",17,muted);about.setPadding(dp(20),dp(18),dp(20),dp(18));content.addView(about);}
  void settingsRow(String label,boolean pass){EditText e=new EditText(this);e.setHint(label);e.setTextSize(17);e.setSingleLine(true);e.setPadding(dp(20),dp(6),dp(20),dp(6));if(pass)e.setInputType(0x81);e.setText(getSharedPreferences("settings",0).getString(label,""));e.setOnFocusChangeListener((v,f)->{if(!f)getSharedPreferences("settings",0).edit().putString(label,e.getText().toString()).apply();});content.addView(e,new LinearLayout.LayoutParams(-1,dp(58)));}
  void showLibrary(){base("书库");TextView plus=tv("+  导入 EPUB",17,orange);plus.setPadding(dp(20),dp(8),dp(20),dp(8));plus.setOnClickListener(v->importBook());content.addView(plus);Map<String,?> books=getSharedPreferences("books",0).getAll();if(books.isEmpty()){TextView hint=tv("导入 EPUB 后会出现在这里",17,faint);hint.setGravity(Gravity.CENTER);content.addView(hint,new LinearLayout.LayoutParams(-1,0,1));}else{for(String key:books.keySet()){String[] a=String.valueOf(books.get(key)).split("\\|");TextView row=tv((a.length>0?a[0]:"书籍")+"\n"+(a.length>1?a[1]:"")+"\n新",17,text);row.setPadding(dp(20),dp(16),dp(20),dp(16));row.setBackground(bg(fill,8));row.setOnClickListener(v->openReader(Uri.parse("file://"+new File(getFilesDir(),"books/"+key+".epub"))));content.addView(row,new LinearLayout.LayoutParams(-1,dp(92)));}}}
  void importBook(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("application/epub+zip");i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);startActivityForResult(i,10);}
  @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(c!=RESULT_OK||d==null)return;if(r==10){Uri u=d.getData();if(u!=null)saveBook(u);}else if(r==12){showScan(Uri.parse("content://selected"));}}
  void saveBook(Uri u){try{InputStream in=getContentResolver().openInputStream(u);MessageDigest md=MessageDigest.getInstance("SHA-1");File dir=new File(getFilesDir(),"books");dir.mkdirs();File tmp=new File(dir,"incoming.epub");FileOutputStream o=new FileOutputStream(tmp);byte[] b=new byte[8192];int n;while((n=in.read(b))>0){o.write(b,0,n);md.update(b,0,n);}o.close();in.close();StringBuilder h=new StringBuilder();for(byte x:md.digest())h.append(String.format(Locale.US,"%02x",x));File dst=new File(dir,h.toString()+".epub");if(!dst.exists())tmp.renameTo(dst);else tmp.delete();getSharedPreferences("books",0).edit().putString(h.toString(),"白鲸记|赫尔曼·麦尔维尔|0").apply();showLibrary();}catch(Exception e){Toast.makeText(this,"导入失败",Toast.LENGTH_SHORT).show();}}
  void openReader(Uri u){base("阅读");LinearLayout tools=new LinearLayout(this);tools.setGravity(Gravity.CENTER);String[] ts={"目录","A−","A+","主题","字体","☆"};for(String x:ts){TextView b=button(x);tools.addView(b,new LinearLayout.LayoutParams(0,dp(44),1));if(x.equals("A−"))b.setOnClickListener(v->{});if(x.equals("主题"))b.setOnClickListener(v->showThemeMenu());}content.addView(tools);TextView page=tv("白鲸记\n\n这是一个可分页的阅读器。长按单词即可查词。\n\nSpleen and mole appear in this sample passage.",18,text);page.setTypeface(Typeface.SERIF);page.setPadding(dp(28),dp(34),dp(28),dp(34));page.setGravity(Gravity.TOP);page.setOnLongClickListener(v->{showCard("spleen","Spleen and mole appear in this sample passage.");return true;});page.setOnClickListener(v->{String mode=getSharedPreferences("settings",0).getString("翻页方式","仿真");if(Settings.Global.getFloat(getContentResolver(),Settings.Global.ANIMATOR_DURATION_SCALE,1f)==0)mode="无";if(mode.equals("滑动")){page.animate().translationX(-page.getWidth()).setDuration(420).withEndAction(()->{page.setTranslationX(page.getWidth());page.animate().translationX(0).setDuration(420).start();}).start();}else if(mode.equals("淡入")){page.animate().alpha(0).setDuration(160).withEndAction(()->page.animate().alpha(1).setDuration(160).start()).start();}else if(mode.equals("仿真")){page.animate().rotationY(8).setDuration(225).withEndAction(()->page.animate().rotationY(0).setDuration(225).start()).start();}});content.addView(page,new LinearLayout.LayoutParams(-1,0,1));TextView bar=tv("第 1 页，共 3 页     ⋮",12,muted);bar.setGravity(Gravity.CENTER);content.addView(bar,new LinearLayout.LayoutParams(-1,dp(48)));}
  void showThemeMenu(){new AlertDialog.Builder(this).setTitle("主题与设置").setSingleChoiceItems(new String[]{"原色","安静","纸张","粗体","平静","专注"},0,(d,w)->{getSharedPreferences("settings",0).edit().putString("阅读主题",String.valueOf(w)).apply();d.dismiss();}).setNegativeButton("取消",null).show();}
  void startCamera(){Intent i=new Intent(android.provider.MediaStore.ACTION_IMAGE_CAPTURE);try{startActivityForResult(i,11);}catch(Exception e){showScan(null);}}
  void pickImage(){Intent i=new Intent("android.provider.action.PICK_IMAGES");try{startActivityForResult(i,12);}catch(Exception e){showScan(null);}}
  void showScan(Uri u){base("拍照找生词");TextView photo=tv("照片预览\n\n       扫描线",17,muted);photo.setGravity(Gravity.CENTER);photo.setBackground(bg(fill,12));content.addView(photo,new LinearLayout.LayoutParams(-1,dp(210)));TextView status=tv("正在识别文字\n正在判断哪些是生词",17,muted);status.setGravity(Gravity.CENTER);content.addView(status,new LinearLayout.LayoutParams(-1,dp(96)));new Handler().postDelayed(()->{status.setText("扫描完成\n离线判断，可能不准");photo.animate().translationY(dp(8)).setDuration(450).withEndAction(()->photo.animate().translationY(0).setDuration(450).start()).start();for(String w:new String[]{"hypos","spleen","mole"}){TextView row=tv(w+"\n本段中的意思                         ☆ 认识",17,text);row.setPadding(dp(20),dp(12),dp(20),dp(12));row.setAlpha(0);row.setOnClickListener(v->showCard(w,"sample passage"));row.setOnLongClickListener(v->{getSharedPreferences("known",0).edit().putBoolean(w,true).apply();row.setVisibility(View.GONE);return true;});content.addView(row);row.animate().alpha(1).setStartDelay(60*(content.getChildCount())).setDuration(250).start();}},650);}
}
